CREATE SCHEMA analytics;
CREATE TABLE analytics."dim_customer" ("customer_id" VARCHAR NOT NULL, "region_group" VARCHAR NOT NULL, "segment" VARCHAR NOT NULL, "registered_date" DATE NOT NULL, "snapshot_date" DATE NOT NULL, PRIMARY KEY(customer_id));
CREATE TABLE analytics."dim_product" ("product_id" VARCHAR NOT NULL, "category" VARCHAR NOT NULL, "unit_price_cents" BIGINT NOT NULL, "currency" VARCHAR NOT NULL, "snapshot_date" DATE NOT NULL, PRIMARY KEY(product_id), CHECK(unit_price_cents >= 0), CHECK(currency = 'TEST'));
CREATE TABLE analytics."fact_order" ("order_id" VARCHAR NOT NULL, "customer_id" VARCHAR NOT NULL, "ordered_at" TIMESTAMP NOT NULL, "paid_at" TIMESTAMP, "status" VARCHAR NOT NULL, "channel" VARCHAR NOT NULL, "gross_amount_cents" BIGINT NOT NULL, "discount_cents" BIGINT NOT NULL, "paid_amount_cents" BIGINT NOT NULL, "currency" VARCHAR NOT NULL, "partition_date" DATE NOT NULL, PRIMARY KEY(order_id), FOREIGN KEY(customer_id) REFERENCES analytics.dim_customer(customer_id), CHECK(status IN ('paid','completed','cancelled')), CHECK(gross_amount_cents >= discount_cents AND discount_cents >= 0), CHECK(currency = 'TEST'), CHECK((status = 'cancelled' AND paid_amount_cents = 0 AND paid_at IS NULL) OR (status != 'cancelled' AND paid_amount_cents = gross_amount_cents - discount_cents AND paid_at >= ordered_at)), CHECK(partition_date = CAST(ordered_at AS DATE)));
CREATE TABLE analytics."fact_order_item" ("order_item_id" VARCHAR NOT NULL, "order_id" VARCHAR NOT NULL, "product_id" VARCHAR NOT NULL, "quantity" INTEGER NOT NULL, "unit_price_cents" BIGINT NOT NULL, "line_amount_cents" BIGINT NOT NULL, "partition_date" DATE NOT NULL, PRIMARY KEY(order_item_id), FOREIGN KEY(order_id) REFERENCES analytics.fact_order(order_id), FOREIGN KEY(product_id) REFERENCES analytics.dim_product(product_id), CHECK(quantity > 0 AND unit_price_cents >= 0), CHECK(line_amount_cents = quantity * unit_price_cents));
CREATE TABLE analytics."fact_event" ("event_id" VARCHAR NOT NULL, "customer_id" VARCHAR NOT NULL, "session_id" VARCHAR NOT NULL, "order_id" VARCHAR NOT NULL, "event_type" VARCHAR NOT NULL, "event_at" TIMESTAMP NOT NULL, "channel" VARCHAR NOT NULL, "partition_date" DATE NOT NULL, PRIMARY KEY(event_id), FOREIGN KEY(customer_id) REFERENCES analytics.dim_customer(customer_id), FOREIGN KEY(order_id) REFERENCES analytics.fact_order(order_id), CHECK(event_type IN ('view','add_to_cart','place_order','pay_order')), CHECK(partition_date = CAST(event_at AS DATE)));
